CREATE TABLE IF NOT EXISTS agentControlSettings (id INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL UNIQUE, killSwitch BOOLEAN NOT NULL DEFAULT FALSE, dailyRunLimit INT NOT NULL DEFAULT 100, dailyHighRiskLimit INT NOT NULL DEFAULT 10, maxWorkflowRuntimeSeconds INT NOT NULL DEFAULT 120, updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agentUsageDaily (id INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, usageDate VARCHAR(10) NOT NULL, runs INT NOT NULL DEFAULT 0, highRiskRuns INT NOT NULL DEFAULT 0, estimatedTokens INT NOT NULL DEFAULT 0, updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX agentUsageDaily_user_date_idx (userId, usageDate));
CREATE TABLE IF NOT EXISTS agentEvents (id INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, eventType VARCHAR(80) NOT NULL, severity ENUM('info','warning','error','critical') NOT NULL DEFAULT 'info', correlationId VARCHAR(180), metadata TEXT, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX agentEvents_user_idx (userId), INDEX agentEvents_created_idx (createdAt), INDEX agentEvents_correlation_idx (correlationId));
